import { ulid } from 'ulid';

/**
 * Identifier rules (guideline §14 リクエストトレーサビリティ).
 *
 * - tenantId: lower-case slug, 2..64 chars. Generated by the tenant registry, never by clients.
 * - correlationId / requestId / eventId: URL-safe tokens, 8..128 chars. Inbound values that
 *   fail validation are replaced (never trusted) so that log injection and unbounded
 *   cardinality are structurally impossible.
 */
export const TENANT_ID_PATTERN = /^[a-z0-9][a-z0-9-]{1,63}$/;
// '=' is allowed because API Gateway request ids are base64-like (e.g. "FZJCgjLstjMEQLA=") and
// are used as the correlationId fallback (found during the first sandbox deployment).
export const SAFE_TOKEN_PATTERN = /^[A-Za-z0-9._:=-]{8,128}$/;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9._:-]{8,128}$/;
export const TENANT_TIERS = ['standard', 'premium', 'enterprise'] as const;
export type TenantTier = (typeof TENANT_TIERS)[number];

export function newId(): string {
  return ulid();
}

export function isValidTenantId(value: unknown): value is string {
  return typeof value === 'string' && TENANT_ID_PATTERN.test(value);
}

export function isSafeToken(value: unknown): value is string {
  return typeof value === 'string' && SAFE_TOKEN_PATTERN.test(value);
}

export function isValidIdempotencyKey(value: unknown): value is string {
  return typeof value === 'string' && IDEMPOTENCY_KEY_PATTERN.test(value);
}

export function parseTenantTier(value: unknown, fallback: TenantTier = 'standard'): TenantTier {
  return typeof value === 'string' && (TENANT_TIERS as readonly string[]).includes(value)
    ? (value as TenantTier)
    : fallback;
}

/** Returns the inbound token when it is safe to use, otherwise a freshly generated one. */
export function acceptOrGenerateToken(value: unknown): { value: string; generated: boolean } {
  if (isSafeToken(value)) {
    return { value, generated: false };
  }
  return { value: newId(), generated: true };
}

/** DynamoDB partition key prefix for pooled multi-tenant tables (guideline §5, §13). */
export function tenantPartitionKey(tenantId: string): string {
  if (!isValidTenantId(tenantId)) {
    throw new Error(`invalid tenantId: ${String(tenantId)}`);
  }
  return `TENANT#${tenantId}`;
}
